.set_list_fid_dropdown {
  display: inline-block;
  line-height: 30px;
  margin-left: 10px;
  position: relative;
  vertical-align: bottom;
}
.set_list_fid_dropdown .setting_btn {
  border: 1px solid #ccc;
  height: 30px;
  width: 30px;
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}
.set_list_fid_dropdown .setting_btn:hover{
  background: #e9f6eb;
  border-color: #bce4c4;
}
.set_list_fid_dropdown .icon-setting {
  color: rgb(102, 102, 102);
}
.set_list_fid_dropdown .setting_btn:hover .icon-setting {
  color: #20a53a;
}
.set_list_fid_dropdown .setting_ul {
  position: absolute;
  z-index: 99;
  background: #fff;
  width: 150px;
  right: 0;
  border-radius: 4px;
  box-shadow: 0px 0px 4px rgba(0, 0, 0, 0.25);
  padding: 10px 0;
  margin-top: 10px;
  display: none;
}
.set_list_fid_dropdown .setting_ul::after {
  content: '';
  position: absolute;
  color: #fff;
  width: 12px;
  height: 12px;
  font-size: 14px;
  top: -7px;
  right: 8px;
  display: inline-block;
  background: #fff;
  transform: rotate(-45deg);
  border-top: 1px solid rgba(0, 0, 0, 0.25);
  border-right: 1px solid rgba(0, 0, 0, 0.25);
}
.setting_ul .setting_ul_li{
  display: flex;
  align-items: center;
  line-height: 27px;
  padding: 0 16px;
  cursor: pointer;
}
.setting_ul .setting_ul_li:hover{
  background: #e9f6eb;
}
.setting_ul .setting_ul_li.disabled {
  cursor: not-allowed;
}

.setting_ul .setting_ul_li i {
  display: inline-block;
  width: 16px;
  height: 16px;
  border: 1px solid #ccc;
  background-color: #fff;
  vertical-align: top;
  position: relative;
  border-radius: 2px;
}
.setting_ul .setting_ul_li.active i {
  colore di sfondo: #20a53a;
  colore del bordo: #20a53a;
}
.setting_ul .setting_ul_li.disabled i {
  colore di sfondo: #edf2fc;
  colore del bordo: #dcdfe6;
}
.setting_ul .setting_ul_li.active.disabled i {
  background-color: #f2f6fc;
  border-color: #dcdfe6;
}
.setting_ul .setting_ul_li.active.disabled i::after{
  border: solid #dcdfe6;
  border-width: 0 2px 2px 0;
}
.setting_ul .setting_ul_li.active i::after{
  content: '';
  position: absolute;
  display: block;
  left: 50%;
  top: 50%;
  margin-left: -2px;
  margin-top: -6px;
  width: 5px;
  height: 10px;
  border: solid #fff;
  border-width: 0 2px 2px 0;
  transform: rotate(45deg);
}
